  const said = padSurface_(x), surf = said === 'text' || padPicked_(x) ? '' : said;
  const opened = !!x.key && typeof PEN_OPEN !== 'undefined' && (PEN_OPEN.has(x.key) || padHasInk_(x));
  if (said === 'text' && !opened) return null;
