    api({ action: 'raiseHand', on: !!h, q: h ? h.q : '', label: h ? h.label : '', personId: USER.personId || '' })
      .then(d => { if (d && d.error) toast('The tutor was not told: ' + d.error); })
      .catch(() => toast(text_('the-tutor-was-not-told-no')));
